"""Defensive cross-asset factor ensemble, Screener 2032-12-23.

Completed daily bars only; one atomic fully-invested (cash=0) rebalance per
10-day decision block. Uses the 10 active factors persisted in
factors/factor_ensemble.json. In the current high-vol / elevated-correlation
VIX-stress bear regime we keep a defensive tilt anchored on beta_VIX_60(neg)
(VIX-safe-haven resilience), trend/momentum as modest secondaries and the
ac1_120d(neg) mean-reversion hedge. No cash sleeve; all 15 tradable assets get
non-negative weights summing to 1.
"""
from math import isfinite
import json
import numpy as np
import pandas as pd
from alphacrafter.sim.utils import (get_account_dict, get_stock_daily_data,
    get_index_daily_data, rebalance_to_weights, register_hook)


def stock(a, n=260):
    try:
        return get_stock_daily_data(a, days=n)
    except Exception:
        return None


def index(a, n=130):
    try:
        return get_index_daily_data(a, days=n)
    except Exception:
        return None


def normz(s):
    s = s.astype(float)
    if len(s) < 3:
        return s * 0.0
    sd = s.std(ddof=0)
    if not isfinite(sd) or sd <= 1e-12:
        return s * 0.0
    return (s - s.mean()) / sd


def kaufman(px, n=20):
    sig = px.diff(n).abs()
    noise = px.diff().abs().rolling(n).sum()
    return sig / noise


def rolling_beta(y, x, n):
    out = pd.DataFrame(index=y.index, columns=y.columns, dtype=float)
    for c in y.columns:
        yy = pd.concat([y[c], x], axis=1).dropna()
        b = (yy.iloc[:, 0].rolling(n).cov(yy.iloc[:, 1])
             / yy.iloc[:, 1].rolling(n).var())
        out[c] = b
    return out


def load_macro(name):
    try:
        df = get_index_daily_data(name, days=400)
        return df.close.astype(float)
    except Exception:
        return None


def factor_panels(panel, R, vix, cny, dxy):
    F = {}
    F['mom_120d_skip5'] = panel / panel.shift(126) - 1
    F['mom_10d_skip5'] = panel / panel.shift(15) - 1
    F['bb_width_20d'] = 4 * panel.rolling(20).std() / panel.rolling(20).mean()
    F['ac1_120d'] = R.rolling(120).apply(
        lambda x: x.autocorr() if x.std() > 0 else np.nan, raw=False)
    F['skew_20d'] = R.rolling(20).skew()
    F['kaufman_eff_20d'] = kaufman(panel, 20)
    F['vol_z_20d'] = R.rolling(20).std() * np.sqrt(252)
    if vix is not None and len(vix):
        F['beta_VIX_60'] = rolling_beta(R, vix.pct_change(), 60)
    if cny is not None and len(cny):
        F['cny_beta_60'] = rolling_beta(R, cny.pct_change(), 60)
    if dxy is not None and len(dxy):
        rdxy = dxy.pct_change()
        F['dxy_corr_change_20_60'] = R.rolling(20).corr(rdxy) - R.rolling(60).corr(rdxy)
    return F


@register_hook
def strategy_hook():
    acct = get_account_dict()
    assets = list(acct.get("watch_list", []))
    if not assets:
        return
    nav = float(acct.get("net_assets") or acct.get("total_assets") or 0.0)

    # ---- load active factor ensemble (capped at 10) ----
    try:
        ens = json.load(open("factors/factor_ensemble.json"))
        sel = [(x["factor_id"], float(x["weight"]), int(x["direction"]))
               for x in ens["selected_factors"]]
    except Exception:
        sel = []
    if not sel:
        # no ensemble this cycle -> preserve current holdings (no change)
        cur = {}
        for p in acct.get("positions", []):
            s = str(p.get("symbol"))
            if s in assets and nav > 0:
                cur[s] = abs(float(p.get("market_value") or 0.0)) / nav
        if cur:
            rebalance_to_weights({a: cur.get(a, 0.0) for a in assets},
                                 forecast_returns={a: 0.0 for a in assets},
                                 horizon_days=10, factor_ids=[])
        else:
            rebalance_to_weights({a: 1.0 / len(assets) for a in assets},
                                 forecast_returns={a: 0.0 for a in assets},
                                 horizon_days=10, factor_ids=[])
        return

    # ---- build completed-bar price panel (visible through prev day only) ----
    frames = {a: stock(a) for a in assets}

